use vstd::prelude::*;

verus! {
    // We make Legendre an external struct so that Verus treats it opaquely,
    // but we can still assert equalities of its fields in ensures clauses.
    #[verifier(external)]
    #[derive(Clone)]
    pub struct Legendre {
        pub coefficients: Vec<f64>,
        pub domain:      [f64; 2],
        pub window:      [f64; 2],
        pub symbol:      String,
    }

    /// Construct a Legendre‐polynomial descriptor.
    /// 
    /// Ensures that all fields of the returned struct are exactly the inputs,
    /// and in particular preserves the special interval property
    /// for [-1.0,1.0].
    fn mk_legendre(
        coef: Vec<f64>,
        domain: [f64; 2],
        window: [f64; 2],
        symbol: String,
    ) -> Legendre
        ensures
            // field‐wise equality
            result.coefficients == coef,
            result.domain       == domain,
            result.window       == window,
            result.symbol       == symbol,
            // special interval property
            (domain == [-1.0, 1.0] ==> result.domain == [-1.0, 1.0]),
            (window == [-1.0, 1.0] ==> result.window == [-1.0, 1.0]),
    {
        Legendre {
            coefficients: coef,
            domain,
            window,
            symbol,
        }
    }
}

fn main() {
    // Example usage (not verified here):
    let c = vec![1.0, 0.0, -0.5];
    let d = [-1.0, 1.0];
    let w = [0.0, 2.0];
    let s = String::from("P2");
    let p = mk_legendre(c.clone(), d, w, s.clone());
    assert!(p.coefficients == c);
    assert!(p.domain       == d);
    assert!(p.window       == w);
    assert!(p.symbol       == s);
}